const { url, discussion, maxTags, fields } = $.input;
if (!url) throw new Error('url is required');

const params = { url };
if (discussion === false) params.discussion = 'false';
if (maxTags && maxTags !== 10) params.maxTags = String(maxTags);
if (fields) params.fields = fields;

return { params };

const resp = $.steps.extractArticle.response || {};
const objects = resp.objects || [];
const article = objects[0] || {};

return {
  title: article.title || resp.title || '',
  author: article.author || '',
  date: article.date || '',
  text: article.text || '',
  html: article.html || '',
  siteName: article.siteName || '',
  pageUrl: article.pageUrl || $.input.url,
  language: resp.humanLanguage || '',
  sentiment: article.sentiment || null,
  tags: (article.tags || []).map(t => ({ label: t.label, score: t.score, count: t.count })),
  categories: (article.categories || []).map(c => ({ name: c.name, score: c.score })),
  images: (article.images || []).map(i => ({ url: i.url, width: i.naturalWidth, height: i.naturalHeight, primary: i.primary || false })),
  numPages: article.numPages || 1,
  summary: article.title ? `Extracted "${article.title}" by ${article.author || 'unknown'} from ${article.siteName || 'unknown site'}` : 'No article found at URL'
};
